/// Raven `gtimer_t` — a single timer with a name, expiration time, and link to next.
///
/// Type definition source: `oracle/codemp/game/g_timer.c:10-15`
#[repr(C)]
#[derive(Clone, Copy)]
pub struct gtimer_t {
    pub name: *const c_char,
    pub time: c_int,
    pub next: *mut gtimer_t,
}

// `#[repr(C)]` POD (raw pointers null-valid + `c_int`); the all-zero image is a
// valid inhabitant — Raven's `g_timerPool` starts zeroed — so the ~384 KB pool
// builds heap-first via `zeroed_box`.
unsafe impl native_platform::ZeroValid for gtimer_t {}

/// Maximum number of timers in the pool (Raven `MAX_GTIMERS`).
/// Source: `oracle/codemp/game/g_timer.c:8`
pub const MAX_GTIMERS: usize = 16384;

// Timer state — file-scope globals per oracle, now GameWorld fields
// (`GameGlobals::g_timerPool`/`g_timers`/`g_timerFreeList`), reached through
// `ctx.world.globals` at every call site below.
// Source: `oracle/codemp/game/g_timer.c:17-19`

/// Raven `TIMER_Clear`.
///
/// Source: `oracle/codemp/game/g_timer.c:27-41`
pub fn TIMER_Clear(ctx: GameContext<'_>) {
    unsafe {
        let world = &mut *ctx.world;

        // Clear all timers for each entity
        for i in 0..MAX_GENTITIES {
            world.globals.g_timers.0[i as usize] = core::ptr::null_mut();
        }

        // Initialize the free list: each timer points to the next one
        for i in 0..MAX_GTIMERS - 1 {
            let next = &mut world.globals.g_timerPool.0[i + 1] as *mut gtimer_t;
            world.globals.g_timerPool.0[i].next = next;
        }
        // Last timer in pool has no next
        world.globals.g_timerPool.0[MAX_GTIMERS - 1].next = core::ptr::null_mut();
        // Free list starts at first timer in pool
        world.globals.g_timerFreeList = &mut world.globals.g_timerPool.0[0];
    }
}

/// Raven `TIMER_Clear2`.
///
/// Source: `oracle/codemp/game/g_timer.c:49-74`
pub fn TIMER_Clear2(ctx: GameContext<'_>, ent: *mut gentity_t) {
    unsafe {
        let world = &mut *ctx.world;

        // Rudimentary safety checks
        if ent.is_null() {
            return;
        }
        let ent_ref = &*ent;
        let entity_num = ent_ref.s.number as usize;

        if entity_num == 0 || entity_num >= MAX_GENTITIES as usize {
            return;
        }

        let mut p = world.globals.g_timers.0[entity_num];

        // No timers at all -> do nothing
        if p.is_null() {
            return;
        }

        // Find the end of this entity's timer list
        while !(*p).next.is_null() {
            p = (*p).next;
        }

        // Splice the lists: attach entity's timer list to free list
        (*p).next = world.globals.g_timerFreeList;
        world.globals.g_timerFreeList = world.globals.g_timers.0[entity_num];
        world.globals.g_timers.0[entity_num] = core::ptr::null_mut();
    }
}

/// Raven `TIMER_GetNew`.
///
/// Source: `oracle/codemp/game/g_timer.c:79-103`
pub fn TIMER_GetNew(ctx: GameContext<'_>, num: c_int, identifier: *const c_char) -> *mut c_void {
    unsafe {
        let world = &mut *ctx.world;
        let num_usize = num as usize;
        let mut p = world.globals.g_timers.0[num_usize];

        // Search for an existing timer with this name
        while !p.is_null() {
            if Q_stricmp((*p).name, identifier) == 0 {
                // Found it
                return p as *mut c_void;
            }

            p = (*p).next;
        }

        // No existing timer with this name was found, so grab one from the free list
        if world.globals.g_timerFreeList.is_null() {
            return core::ptr::null_mut();
        }

        p = world.globals.g_timerFreeList;
        world.globals.g_timerFreeList = (*world.globals.g_timerFreeList).next;
        (*p).next = world.globals.g_timers.0[num_usize];
        world.globals.g_timers.0[num_usize] = p;
        p as *mut c_void
    }
}

/// Raven `TIMER_GetExisting`.
///
/// Source: `oracle/codemp/game/g_timer.c:106-121`
pub fn TIMER_GetExisting(
    ctx: GameContext<'_>,
    num: c_int,
    identifier: *const c_char,
) -> *mut c_void {
    unsafe {
        let world = &mut *ctx.world;
        let num_usize = num as usize;
        let mut p = world.globals.g_timers.0[num_usize];

        while !p.is_null() {
            if Q_stricmp((*p).name, identifier) == 0 {
                // Found it
                return p as *mut c_void;
            }

            p = (*p).next;
        }

        core::ptr::null_mut()
    }
}

/// Raven `TIMER_Set`.
///
/// Source: `oracle/codemp/game/g_timer.c:129-139`
pub fn TIMER_Set(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    identifier: *const c_char,
    duration: c_int,
) {
    unsafe {
        if ent.is_null() {
            return;
        }
        let ent_ref = &*ent;
        let timer = TIMER_GetNew(ctx, ent_ref.s.number, identifier) as *mut gtimer_t;

        if timer.is_null() {
            return;
        }

        (*timer).name = identifier;
        (*timer).time = (*ctx.world).level.time + duration;
    }
}

/// Raven `TIMER_Get`.
///
/// Source: `oracle/codemp/game/g_timer.c:147-157`
pub fn TIMER_Get(ctx: GameContext<'_>, ent: *mut gentity_t, identifier: *const c_char) -> c_int {
    unsafe {
        if ent.is_null() {
            return -1;
        }
        let ent_ref = &*ent;
        let timer = TIMER_GetExisting(ctx, ent_ref.s.number, identifier) as *mut gtimer_t;

        if timer.is_null() {
            return -1;
        }

        (*timer).time
    }
}

/// Raven `TIMER_Done`.
///
/// Source: `oracle/codemp/game/g_timer.c:165-175`
pub fn TIMER_Done(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    identifier: *const c_char,
) -> qboolean {
    unsafe {
        if ent.is_null() {
            return qtrue;
        }
        let ent_ref = &*ent;
        let timer = TIMER_GetExisting(ctx, ent_ref.s.number, identifier) as *mut gtimer_t;

        if timer.is_null() {
            return qtrue;
        }

        if (*timer).time < (*ctx.world).level.time {
            qtrue
        } else {
            qfalse
        }
    }
}

/// Raven `TIMER_RemoveHelper`.
///
/// Scans an entity's timer list to remove a given timer from the list
/// and put it on the free list.
///
/// Source: `oracle/codemp/game/g_timer.c:187-211`
pub fn TIMER_RemoveHelper(ctx: GameContext<'_>, num: c_int, timer: *mut c_void) {
    unsafe {
        let world = &mut *ctx.world;
        let num_usize = num as usize;
        let timer = timer as *mut gtimer_t;

        let mut p = world.globals.g_timers.0[num_usize];

        // Special case: first timer in list
        if p == timer {
            world.globals.g_timers.0[num_usize] = (*world.globals.g_timers.0[num_usize]).next;
            (*timer).next = world.globals.g_timerFreeList;
            world.globals.g_timerFreeList = timer;
            return;
        }

        // Find the predecessor
        while !p.is_null() && (*p).next != timer {
            p = (*p).next;
        }

        // Raven's predecessor walk has no bounds check and dereferences NULL if
        // `timer` isn't linked under this entity (UB); return instead.
        if p.is_null() {
            return; // Timer not found, shouldn't happen
        }

        // Rewire
        (*p).next = (*timer).next;
        (*timer).next = world.globals.g_timerFreeList;
        world.globals.g_timerFreeList = timer;
    }
}

/// Raven `TIMER_Done2`.
///
/// Returns false if timer has been started but is not done, or if timer was never started.
/// Returns true if timer is done (optionally removing it from the list).
///
/// Source: `oracle/codemp/game/g_timer.c:223-242`
pub fn TIMER_Done2(
    ctx: GameContext<'_>,
    ent: *mut gentity_t,
    identifier: *const c_char,
    remove: qboolean,
) -> qboolean {
    unsafe {
        if ent.is_null() {
            return qfalse;
        }
        let ent_ref = &*ent;
        let timer = TIMER_GetExisting(ctx, ent_ref.s.number, identifier) as *mut gtimer_t;

        if timer.is_null() {
            return qfalse;
        }

        let res = (*timer).time < (*ctx.world).level.time;

        if res && remove == qtrue {
            // Put it back on the free list
            TIMER_RemoveHelper(ctx, ent_ref.s.number, timer as *mut c_void);
        }

        if res {
            qtrue
        } else {
            qfalse
        }
    }
}

