/// Raven `TIMER_Remove`.
///
/// Utility to get rid of any timer.
///
/// Source: `oracle/codemp/game/g_timer.c:267-278`
pub fn TIMER_Remove(ctx: GameContext<'_>, ent: *mut gentity_t, identifier: *const c_char) {
    unsafe {
        if ent.is_null() {
            return;
        }
        let ent_ref = &*ent;
        let timer = TIMER_GetExisting(ctx, ent_ref.s.number, identifier) as *mut gtimer_t;

        if timer.is_null() {
            return;
        }

        // Put it back on the free list
        TIMER_RemoveHelper(ctx, ent_ref.s.number, timer as *mut c_void);
    }
}

/// Raven `TIMER_Start`.
///
/// Source: `oracle/codemp/game/g_timer.c:286-294`
pub fn TIMER_Start(
    ctx: GameContext<'_>,
    self_: *mut gentity_t,
    identifier: *const c_char,
    duration: c_int,
) -> qboolean {
    if TIMER_Done(ctx, self_, identifier) == qtrue {
        TIMER_Set(ctx, self_, identifier, duration);
        qtrue
    } else {
        qfalse
    }
}
